<?php $title='Menus';require __DIR__.'/_layout.php';if(!can_manage('menus'))exit('Forbidden');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$vals=[];foreach(['name'] as $f)$vals[] = trim($_POST[$f]??'');$cols=implode(',',['name']);$qs=implode(',',array_fill(0,count($vals),'?'));$st=db()->prepare("INSERT INTO menus ($cols) VALUES ($qs)");$st->execute($vals);flash('success','Saved.');redirect('menus.php');}if(isset($_GET['delete'])){db()->prepare("DELETE FROM menus WHERE id=?")->execute([(int)$_GET['delete']]);redirect('menus.php');}$rows=db()->query("SELECT * FROM menus ORDER BY id DESC")->fetchAll();?><div class="toolbar"><h1>Menus</h1></div><form class="form" method="post"><?=csrf_field()?><label>Name</label><input name="name" required><button>Save</button></form><section class="section"><table class="table"><tr><th>ID</th><th>name</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e(mb_strimwidth($r["name"]??"",0,80,"…"))?></td><td><a data-confirm="Delete?" href="menus.php?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/_footer.php';?>